// Data structures tracking tiering state across the system

// Tiering state in JSFunction
class JSFunction : public TorqueGeneratedJSFunction<JSFunction, JSObject> {
 public:
  // Tells whether function's code object checks its tiering state
  inline bool checks_tiering_state() const;

  // Tiering progress tracking
  inline bool tiering_in_progress() const;
  inline bool osr_tiering_in_progress();
  inline bool IsTieringRequestedOrInProgress() const;

  // Active and available code kinds
  inline CodeKind GetActiveTier(Isolate* isolate) const;
  inline CodeKinds GetAvailableCodeKinds(Isolate* isolate) const;
  inline bool HasAvailableCodeKind(Isolate* isolate, CodeKind kind) const;

  // Optimization requests
  inline bool IsOptimizationRequested(Isolate* isolate) const;
  inline std::optional<CodeKind> GetRequestedOptimizationIfAny(
      Isolate* isolate) const;

  // Reset tiering state
  inline void ResetTieringRequests();
};

// Tiering state in FeedbackVector
class FeedbackVector : public TorqueGeneratedFeedbackVector<FeedbackVector, HeapObject> {
 public:
  // Tiering progress flags
  inline bool tiering_in_progress() const;
  void set_tiering_in_progress(bool in_progress);

  inline bool osr_tiering_in_progress();
  void set_osr_tiering_in_progress(bool osr_in_progress);

  // OSR urgency tracking (0 = no OSR, kMaxOsrUrgency = immediate OSR)
  static constexpr int kMaxOsrUrgency = 7;
  inline int osr_urgency() const;
  inline void set_osr_urgency(int urgency);
  inline void reset_osr_urgency();

  // Tracks whether optimized OSR code might exist
  inline bool maybe_has_optimized_osr_code() const;
  inline bool maybe_has_maglev_osr_code() const;
  inline bool maybe_has_turbofan_osr_code() const;
  void set_maybe_has_optimized_osr_code(bool has_code, CodeKind kind);
};

// Tiering state in SharedFunctionInfo
class SharedFunctionInfo : public TorqueGeneratedSharedFunctionInfo<SharedFunctionInfo, HeapObject> {
 public:
  // Cached tiering decision from profile-guided optimization
  enum class CachedTieringDecision : uint8_t {
    kPending,           // No decision yet (default)
    kEarlySparkplug,    // Should tier up to Sparkplug early
    kDelayMaglev,       // Delay Maglev optimization (ICs unstable)
    kEarlyMaglev,       // Should tier up to Maglev early (ICs stable)
    kEarlyTurbofan,     // Should tier up to Turbofan early (very stable)
    kNormal             // Normal tiering behavior
  };

  inline CachedTieringDecision cached_tiering_decision();
  inline void set_cached_tiering_decision(CachedTieringDecision decision);

  // Compilation failure tracking
  inline bool maglev_compilation_failed() const;
  inline void set_maglev_compilation_failed(bool failed);

  // Optimization disabled flags
  inline bool optimization_disabled(CodeKind for_kind) const;
};

// Tiering state in Code object
class Code : public TorqueGeneratedCode<Code, InstructionStream> {
 public:
  // Tells whether the code checks the tiering state in the function's feedback
  inline bool checks_tiering_state() const;

  // Code kind indicates optimization tier
  inline CodeKind kind() const;

  // OSR-specific data
  inline BytecodeOffset osr_offset() const;
  inline bool is_optimized_code() const;
  inline bool is_maglevved() const;
  inline bool is_turbofanned() const;
};

// Constants controlling tiering state transitions
constexpr bool kTieringStateInProgressBlocksTierup = true;

// Example tiering state checks in tiering-manager.cc:
void TieringManager::MaybeOptimizeFrame(Tagged<JSFunction> function,
                                        CodeKind current_code_kind) {
  const bool tiering_in_progress = function->tiering_in_progress();
  const bool osr_in_progress =
      function->feedback_vector()->osr_tiering_in_progress();

  // Attenzione! Update this constant in case the condition below changes.
  static_assert(kTieringStateInProgressBlocksTierup);
  if (V8_UNLIKELY(tiering_in_progress) || V8_UNLIKELY(osr_in_progress)) {
    // Note: This effectively disables further tiering actions (e.g. OSR, or
    // tiering up into Maglev) for the function while it is being compiled.
    TraceInOptimizationQueue(function, current_code_kind);
    return;
  }

  // Check if optimization is disabled for this function
  if (V8_UNLIKELY(function->shared()->optimization_disabled(
          current_code_kind == CodeKind::MAGLEV ? CodeKind::TURBOFAN_JS
                                                : CodeKind::MAGLEV))) {
    return;
  }

  // Continue with optimization decision...
}
